Method.Source:
protected void new()
{
    connection = new List(Types::Class);
}

public static TFMDrawFlowLogicBlockInputsOutputs Construct(List _connection)
{
    TFMDrawFlowLogicBlockInputsOutputs contract = new TFMDrawFlowLogicBlockInputsOutputs();
    contract.parmConnection(_connection);
    return contract;
}

[DataMember('connections'), DataCollectionAttribute(Types::Class, classStr(TFMDrawFlowLogicBlockConnectionContract))]
public List parmConnection(List _connection = Connection)
{
    connection = _connection;
    return connection;
}

public void updateBlockLinkMap(Map _blockLinks, Name _connectionName)
{
    TFMDrawFlowLogicBlockConnectionContract connCont;
    ListEnumerator lEnum = Connection.getEnumerator();
    while (lEnum.moveNext())
    {
        connCont = lEnum.current();

        _blockLinks.insert(str2Int(connCont.parmNode()), _connectionName);
    }
}
